using UnityEngine;

namespace Astrea;

public class OmenEffectFeedback : FeedbackInstance
{
	[Header("Effect")]
	[SerializeField]
	private string removingEffectID = "WearOff";

	public void PlayOmenFeedback(OmenData omenData, Vector3 unitPosition)
	{
		SetupOmenFeedback(omenData);
		PlayFeedback(unitPosition);
	}

	private void SetupOmenFeedback(OmenData omenData)
	{
		iconImage.sprite = omenData.OmenSprite;
		shadowImage.sprite = omenData.OmenSprite;
		string omenName = omenData.GetOmenName();
		valueText.SetText(GetResourceNameWithLineBreakForFeedback(omenName));
		AdjustTextSize(omenName, wearOff: false);
		valueText.color = Color.black;
	}

	public void PlayEffectFeedback(Effect effect, int amount, Vector3 unitPosition)
	{
		SetupEffectFeedback(effect, wearOff: false);
		if (amount > 0)
		{
			string text = "";
			text = ((amount < EffectsValues.INFINITY) ? amount.ToString() : "∞");
			valueText.SetText(valueText.text.Insert(0, $"{text} "));
		}
		PlayFeedback(unitPosition);
	}

	public void PlayRemoveEffectFeedback(Effect effect, Vector3 unitPosition)
	{
		SetupEffectFeedback(effect, wearOff: true);
		valueText.SetText(valueText.text + "\n" + ReferenceSingleton<LocalizationManager>.Instance.GetLocalizedString(removingEffectID));
		PlayFeedback(unitPosition);
	}

	public void PlayIncreaseDecreaseEffectFeedback(Effect effect, Vector3 unitPosition, int amount)
	{
		SetupEffectFeedback(effect, wearOff: false);
		if (amount >= EffectsValues.INFINITY)
		{
			valueText.SetText(valueText.text.Insert(0, string.Format("{0} ", "∞")));
		}
		else
		{
			string arg = ((amount > 0) ? "+" : "");
			valueText.SetText(valueText.text.Insert(0, $"{arg}{amount.ToString()} "));
		}
		PlayFeedback(unitPosition);
	}

	private void SetupEffectFeedback(Effect effect, bool wearOff)
	{
		iconImage.sprite = effect.EffectSprite;
		shadowImage.sprite = effect.EffectSprite;
		string effectName = effect.GetEffectName();
		valueText.SetText(GetResourceNameWithLineBreakForFeedback(effectName));
		AdjustTextSize(effectName, wearOff);
		valueText.color = (effect.EnableColorReference ? effect.EffectColorReference.Value : effect.EffectColor);
	}

	private string GetResourceNameWithLineBreakForFeedback(string resourceName)
	{
		string text = "";
		if (LanguagesIndexes.IsIgnoreLineBreakOnEffectFeedback())
		{
			text = resourceName;
		}
		else
		{
			string localizedSpace = ReferenceSingleton<LocalizationManager>.Instance.GetLocalizedSpace();
			string[] array = resourceName.Split(' ');
			if (array.Length == 4)
			{
				text = text + array.First() + localizedSpace + array[1] + "\n";
				text = text + array[2] + localizedSpace + array.Last();
			}
			else if (array.Length != 3)
			{
				text = ((array.Length != 2) ? resourceName : ((array.First().Length > 2 && array.Last().Length > 2) ? resourceName.Replace(" ", "\n") : resourceName));
			}
			else
			{
				int num = -1;
				int num2 = 10000;
				for (int i = 0; i < array.Length; i++)
				{
					if (array[i].Length < num2)
					{
						num2 = array[i].Length;
						num = i;
					}
				}
				if (num == array.Length - 1)
				{
					for (int j = 0; j < array.Length; j++)
					{
						text = ((j != array.Length - 1) ? ((j != array.Length - 2) ? (text + array[j] + "\n") : (text + array[j] + localizedSpace)) : (text + array[j]));
					}
				}
				else
				{
					int num3 = -1;
					int num4 = 1000;
					for (int k = 0; k < array.Length; k++)
					{
						if (k != num && array[k].Length >= 3 && array[k].Length < num4)
						{
							num4 = array[k].Length;
							num3 = k;
						}
					}
					for (int l = 0; l < array.Length; l++)
					{
						if (l == num3)
						{
							text = ((l >= num) ? (text + " \n" + array[num] + localizedSpace + array[l]) : (text + array[l] + localizedSpace + array[num] + "\n"));
						}
						else if (l != num)
						{
							text += array[l];
						}
					}
				}
			}
		}
		return text;
	}

	private void AdjustTextSize(string resourceName, bool wearOff)
	{
		if (!LanguagesIndexes.IsIgnoreLineBreakOnEffectFeedback())
		{
			string[] array = resourceName.Split(' ');
			float num = 0f;
			num = ((array.Length >= 2) ? 80f : ((resourceName.Length < 9) ? 60f : 40f));
			if (wearOff)
			{
				num += 40f;
			}
			RectTransform rectTransform = valueText.rectTransform;
			rectTransform.sizeDelta = new Vector2(rectTransform.sizeDelta.x, num);
		}
	}
}
